import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort, CountMemberLoansPort,
        LoadActiveLoansPort, LoadLoanHistoryPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public int countLoans(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public List<ActiveLoan> loadActiveLoans(UUID memberId, int page, int size) {
        return loanJpaRepository.findActiveWithTitle(memberId, PageRequest.of(page, size)).stream()
                .map(row -> {
                    LoanJpaEntity l = (LoanJpaEntity) row[0];
                    return new ActiveLoan(l.getId(), l.getBookId(), (String) row[1], l.getLoanedAt(), l.getDueAt());
                })
                .toList();
    }

    @Override
    public List<LoanHistoryEntry> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findHistoryWithTitle(memberId).stream()
                .map(row -> new LoanHistoryEntry(loanMapper.toDomain((LoanJpaEntity) row[0]), (String) row[1]))
                .toList();
    }
}
