package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadMonthlyLoansPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadMonthlyLoansPort loadMonthlyLoansPort;

    public GetMonthlyStatsService(LoadMonthlyLoansPort loadMonthlyLoansPort) {
        this.loadMonthlyLoansPort = loadMonthlyLoansPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        YearMonth ym;
        try {
            ym = YearMonth.of(year, month);
        } catch (DateTimeException e) {
            throw new IllegalArgumentException("invalid year/month: " + year + "/" + month);
        }
        int loanCount = loadMonthlyLoansPort.loadLoansLoanedBetween(ym.atDay(1), ym.atEndOfMonth()).size();
        List<Loan> returned = loadMonthlyLoansPort.loadLoansReturnedBetween(ym.atDay(1), ym.atEndOfMonth());
        int overdueCount = (int) returned.stream().filter(l -> l.lateFee() > 0).count();
        int lateFeeTotal = returned.stream().mapToInt(Loan::lateFee).sum();
        return new MonthlyStats(year, month, loanCount, returned.size(), overdueCount, lateFeeTotal);
    }
}
