package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void counts_loans_by_loan_month_and_returns_by_return_month() throws Exception {
        String member = create("/members", "{\"name\":\"통계\"}", "memberId");
        // 2031-01-10 대출(기한 01-24) → 2031-02-03 반납: 10일 연체, 연체료 1000
        String b1 = create("/books", "{\"title\":\"A\"}", "id");
        String l1 = loanAt(b1, member, "2031-01-10");
        // 2031-01-20 대출 → 2031-01-25 반납: 연체 아님
        String b2 = create("/books", "{\"title\":\"B\"}", "id");
        String l2 = loanAt(b2, member, "2031-01-20");
        // 2031-01-28 대출, 미반납
        String b3 = create("/books", "{\"title\":\"C\"}", "id");
        loanAt(b3, member, "2031-01-28");
        returnAt(l1, "2031-02-03");
        returnAt(l2, "2031-01-25");

        mockMvc.perform(get("/stats/monthly?year=2031&month=1")).andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2031))
                .andExpect(jsonPath("$.month").value(1))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(1))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
        mockMvc.perform(get("/stats/monthly?year=2031&month=2")).andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(1))
                .andExpect(jsonPath("$.overdueCount").value(1))
                .andExpect(jsonPath("$.lateFeeTotal").value(1000));
    }

    @Test
    void month_without_activity_is_all_zero() throws Exception {
        mockMvc.perform(get("/stats/monthly?year=1999&month=7")).andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly?year=2031&month=13")).andExpect(status().isBadRequest());
    }

    private String loanAt(String bookId, String memberId, String loanedAt) throws Exception {
        return create("/loans", "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                + "\",\"loanedAt\":\"" + loanedAt + "\"}", "loanId");
    }

    private void returnAt(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/" + loanId + "/return").contentType(MediaType.APPLICATION_JSON)
                .content("{\"returnedAt\":\"" + returnedAt + "\"}")).andExpect(status().isOk());
    }

    private String create(String path, String json, String idField) throws Exception {
        String body = mockMvc.perform(post(path).contentType(MediaType.APPLICATION_JSON).content(json))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get(idField).asText();
    }
}
