33	        int overdueCount = (int) returned.stream().filter(l -> l.lateFee() > 0).count();
34	        int lateFeeTotal = returned.stream().mapToInt(Loan::lateFee).sum();
35	        return new MonthlyStats(year, month, loanCount, returned.size(), overdueCount, lateFeeTotal);
36	    }
37	}
